NOTO_NAME = "noto"

# v2.3.28 (issue #29): 版面检测的推理尺寸上限。
# 显存/内存大致按 imgsz 的平方涨，实测同一张真实杂志页（2160×2945）：
#   imgsz=2048 → 2.9s / 0.49GB      imgsz=2944（封顶前）→ 6.0s / 1.10GB
# 换成更大的页（2550×3300，imgsz=3296）就是 20.8s / 3.10GB；400dpi 扫描书
# （页高 4400pt）外推单次推理要 7~8GB。
# 取 2048 而不是模型默认的 1024：实测 5 页真实杂志版面，与封顶前的检出结果相比，
# 2048 的框匹配率 95.4%、类别一致率 90.8%，而 1024 只有 88.5% / 82.8%。
# 目的是止住内存暴涨，不是改变既有排版行为，所以选更保守的 2048。
LAYOUT_MAX_IMGSZ = 2048

noto_list = [
    "am",  # Amharic
    "ar",  # Arabic
    "bn",  # Bengali
    "bg",  # Bulgarian
    "chr",  # Cherokee
    "el",  # Greek
    "gu",  # Gujarati
    "iw",  # Hebrew
    "hi",  # Hindi
    "kn",  # Kannada
    "ml",  # Malayalam
    "mr",  # Marathi
    "ru",  # Russian
    "sr",  # Serbian
    "ta",  # Tamil
    "te",  # Telugu
    "th",  # Thai
    "ur",  # Urdu
    "uk",  # Ukrainian
]


def check_files(files: List[str]) -> List[str]:
    files = [
        f for f in files if not f.startswith("http://")
    ]  # exclude online files, http
    files = [
        f for f in files if not f.startswith("https://")
    ]  # exclude online files, https
    missing_files = [file for file in files if not os.path.exists(file)]
    return missing_files


def _ensure_plaintext_prompt():
    """让自定义 prompt 按纯文本模板处理（issue #31）。

    上游 macOS 版 ``BaseTranslator.prompt`` 是
    ``return eval(prompt.safe_substitute(context))`` —— 要求模板替换后必须是
    一段合法的 Python 字面量（list of dict）。术语库注入生成的是自然语言纯文本，
    一 eval 就 SyntaxError，每段都失败。Windows 版用的是 safe_substitute 直出，
    这里与之对齐。

    放在 high_level 而不是界面层，是因为这里是所有入口（GUI / CLI / 库调用）
    的必经之路，放界面层的话 CLI 路径仍然会踩坑。
    """
    from pdf2zh.translator import BaseTranslator
    if getattr(BaseTranslator, "_p2z_prompt_plaintext", False):
        return

    def _prompt(self, text, prompt_template=None):
        if prompt_template is not None:
            try:
                return [{
                    "role": "user",
                    "content": prompt_template.safe_substitute({
                        "lang_in": self.lang_in,
                        "lang_out": self.lang_out,
                        "text": text,
                    }),
                }]
            except Exception:
                pass   # 模板有问题就退回默认 prompt，不要让整篇翻译失败
        return [
            {"role": "system",
             "content": "You are a professional,authentic machine translation engine."},
            {"role": "user",
             "content": (f"Translate the following markdown source text to {self.lang_out}. "
                         "Keep the formula notation {v*} unchanged. "
                         "Output translation directly without any additional text.\n"
                         f"Source Text: {text}\nTranslated Text:")},
        ]

    BaseTranslator.prompt = _prompt
    BaseTranslator._p2z_prompt_plaintext = True


def translate_patch(
    inf: BinaryIO,
    pages: Optional[list[int]] = None,
    vfont: str = "",
    vchar: str = "",
    thread: int = 0,
    doc_zh: Document = None,
    lang_in: str = "",
    lang_out: str = "",
    service: str = "",
    noto_name: str = "",
    noto: Font = None,
    callback: object = None,
    cancellation_event: asyncio.Event = None,
    model: OnnxModel = None,
    envs: Dict = None,
    prompt: List = None,
    scan_mode: bool = False,
    **kwarg: Any,
) -> None:
    rsrcmgr = PDFResourceManager()
    layout = {}
    device = TranslateConverter(
        rsrcmgr,
        vfont,
        vchar,
        thread,
        layout,
        lang_in,
        lang_out,
        service,
        noto_name,
        noto,
        envs,
        prompt,
        scan_mode=scan_mode,
    )

    assert device is not None
    obj_patch = {}
    interpreter = PDFPageInterpreterEx(rsrcmgr, device, obj_patch)
    if pages:
        total_pages = len(pages)
    else:
        total_pages = doc_zh.page_count

    parser = PDFParser(inf)
    doc = PDFDocument(parser)
    with tqdm.tqdm(total=total_pages) as progress:
        for pageno, page in enumerate(PDFPage.create_pages(doc)):
            if cancellation_event and cancellation_event.is_set():
                raise CancelledError("task cancelled")
            if pages and (pageno not in pages):
                continue
            progress.update()
            if callback:
                callback(progress)
            page.pageno = pageno
            pix = doc_zh[page.pageno].get_pixmap()
            image = np.fromstring(pix.samples, np.uint8).reshape(
                pix.height, pix.width, 3
            )[:, :, ::-1]
            # v2.3.28 (issue #29): 推理尺寸原本直接取页面高度，没有上限。扫描版电子书的
            # 页面盒子常按扫描像素记（如 2550×3300），算出来 imgsz=3296，单次推理就要 3.1GB。
            # predict() 内部先 resize_and_pad_image 再 scale_boxes 还原到原图坐标，
            # 所以封顶不影响输出的框坐标。
            # A4(842pt)/Letter(792pt)/Legal(1008pt) 算出来都远低于 2048，行为完全不变；
            # 本机 2381 份 PDF 里只有 35 份（1.5%）页高超过 1024pt。
            page_layout = model.predict(
                image, imgsz=min(int(pix.height / 32) * 32, LAYOUT_MAX_IMGSZ)
            )[0]
            # kdtree 是不可能 kdtree 的，不如直接渲染成图片，用空间换时间
            box = np.ones((pix.height, pix.width))
            h, w = box.shape
            vcls = ["abandon", "figure", "table", "isolate_formula", "formula_caption"]
            for i, d in enumerate(page_layout.boxes):
                if page_layout.names[int(d.cls)] not in vcls:
                    x0, y0, x1, y1 = d.xyxy.squeeze()
                    x0, y0, x1, y1 = (
                        np.clip(int(x0 - 1), 0, w - 1),
                        np.clip(int(h - y1 - 1), 0, h - 1),
                        np.clip(int(x1 + 1), 0, w - 1),
                        np.clip(int(h - y0 + 1), 0, h - 1),
                    )
                    box[y0:y1, x0:x1] = i + 2
            for i, d in enumerate(page_layout.boxes):
                if page_layout.names[int(d.cls)] in vcls:
                    x0, y0, x1, y1 = d.xyxy.squeeze()
                    x0, y0, x1, y1 = (
                        np.clip(int(x0 - 1), 0, w - 1),
                        np.clip(int(h - y1 - 1), 0, h - 1),
                        np.clip(int(x1 + 1), 0, w - 1),
                        np.clip(int(h - y0 + 1), 0, h - 1),
                    )
                    box[y0:y1, x0:x1] = 0
            layout[page.pageno] = box
            # 新建一个 xref 存放新指令流
            page.page_xref = doc_zh.get_new_xref()  # hack 插入页面的新 xref
            doc_zh.update_object(page.page_xref, "<<>>")
            doc_zh.update_stream(page.page_xref, b"")
            doc_zh[page.pageno].set_contents(page.page_xref)
            interpreter.process_page(page)
            # v2.3.28 (issue #29): 这一页的版面数组到这里就用完了 —— converter 是在
            # process_page 内同步读 self.layout[pageid] 的，循环之后再无人引用。
            # 不释放的话整本书的数组会一直堆着：每页 = 页宽×页高×8 字节，
            # Letter 页 3.7MB，2550×3300 的扫描页 64MB，500 页就是 1.8GB ~ 31GB。
            layout.pop(page.pageno, None)

    device.close()
    return obj_patch


def translate_stream(
    stream: bytes,
    pages: Optional[list[int]] = None,
    lang_in: str = "",
    lang_out: str = "",
    service: str = "",
    thread: int = 0,
    vfont: str = "",
    vchar: str = "",
    callback: object = None,
    cancellation_event: asyncio.Event = None,
    model: OnnxModel = None,
    envs: Dict = None,
    prompt: List = None,
    scan_mode: bool = False,
    glossary: dict = None,
    **kwarg: Any,
):
    # issue #31: 术语库注入 prompt。
    # 之前 macOS 版这里完全没有 glossary 参数，界面上编辑/导入的术语库一个字
    # 都不会影响翻译结果（Windows 版是通的）。行为与 Windows 版保持一致。
    if glossary:
        _ensure_plaintext_prompt()
        glossary_text = "\n".join(f"{k} -> {v}" for k, v in glossary.items())
        head = ("IMPORTANT: Use the following terminology mapping when translating:\n"
                f"{glossary_text}\n\n")
        if prompt:
            base = prompt.template if hasattr(prompt, "template") else str(prompt)
        else:
            base = "Translate the following text from $lang_in to $lang_out:\n$text"
        prompt = Template(head + base)

    font_list = [("tiro", None)]

    font_path = download_remote_fonts(lang_out.lower())
    noto_name = NOTO_NAME
    noto = Font(noto_name, font_path)
    font_list.append((noto_name, font_path))

    doc_en = Document(stream=stream)
    stream = io.BytesIO()
    doc_en.save(stream)
    doc_zh = Document(stream=stream)
    page_count = doc_zh.page_count
    # font_list = [("GoNotoKurrent-Regular.ttf", font_path), ("tiro", None)]
    font_id = {}
    for page in doc_zh:
        for font in font_list:
            font_id[font[0]] = page.insert_font(font[0], font[1])
    xreflen = doc_zh.xref_length()
    for xref in range(1, xreflen):
        for label in ["Resources/", ""]:  # 可能是基于 xobj 的 res
            try:  # xref 读写可能出错
                font_res = doc_zh.xref_get_key(xref, f"{label}Font")
                if font_res[0] == "dict":
                    for font in font_list:
                        font_exist = doc_zh.xref_get_key(xref, f"{label}Font/{font[0]}")
                        if font_exist[0] == "null":
                            doc_zh.xref_set_key(
                                xref,
                                f"{label}Font/{font[0]}",
                                f"{font_id[font[0]]} 0 R",
                            )
            except Exception:
                pass

    fp = io.BytesIO()

    doc_zh.save(fp)
    obj_patch: dict = translate_patch(fp, **locals())

    for obj_id, ops_new in obj_patch.items():
        # ops_old=doc_en.xref_stream(obj_id)
        # print(obj_id)
        # print(ops_old)
        # print(ops_new.encode())
        doc_zh.update_stream(obj_id, ops_new.encode())

    doc_en.insert_file(doc_zh)
    for id in range(page_count):
        doc_en.move_page(page_count + id, id * 2 + 1)

    # Mac patch: subset_fonts 在某些 PDF 字体表不规范时会抛 TypeError/ValueError，
    # 不影响翻译结果，跳过即可（pymupdf 1.26 / Python 3.9 兼容 + 不规范字体兜底）
    try:
        doc_zh.subset_fonts(fallback=True)
    except Exception:
        pass
    try:
        doc_en.subset_fonts(fallback=True)
    except Exception:
        pass
    return (
        doc_zh.write(deflate=True, garbage=3, use_objstms=1),
        doc_en.write(deflate=True, garbage=3, use_objstms=1),
    )


def convert_to_pdfa(input_path, output_path):
    """
    Convert PDF to PDF/A format

    Args:
        input_path: Path to source PDF file
        output_path: Path to save PDF/A file
    """
    from pikepdf import Dictionary, Name, Pdf

    # Open the PDF file
    pdf = Pdf.open(input_path)

    # Add PDF/A conformance metadata
    metadata = {
        "pdfa_part": "2",
        "pdfa_conformance": "B",
        "title": pdf.docinfo.get("/Title", ""),
        "author": pdf.docinfo.get("/Author", ""),
        "creator": "PDF Math Translate",
    }

    with pdf.open_metadata() as meta:
        meta.load_from_docinfo(pdf.docinfo)
        meta["pdfaid:part"] = metadata["pdfa_part"]
        meta["pdfaid:conformance"] = metadata["pdfa_conformance"]

    # Create OutputIntent dictionary
    output_intent = Dictionary(
        {
            "/Type": Name("/OutputIntent"),
            "/S": Name("/GTS_PDFA1"),
            "/OutputConditionIdentifier": "sRGB IEC61966-2.1",
            "/RegistryName": "http://www.color.org",
            "/Info": "sRGB IEC61966-2.1",
        }
    )

    # Add output intent to PDF root
    if "/OutputIntents" not in pdf.Root:
        pdf.Root.OutputIntents = [output_intent]
    else:
        pdf.Root.OutputIntents.append(output_intent)

    # Save as PDF/A
    pdf.save(output_path, linearize=True)
    pdf.close()


def translate(
    files: list[str],
    output: str = "",
    pages: Optional[list[int]] = None,
    lang_in: str = "",
    lang_out: str = "",
    service: str = "",
    thread: int = 0,
    vfont: str = "",
    vchar: str = "",
    callback: object = None,
    compatible: bool = False,
    cancellation_event: asyncio.Event = None,
    model: OnnxModel = None,
    envs: Dict = None,
    prompt: List = None,
    scan_mode: bool = False,
    glossary: dict = None,     # issue #31: 术语库，经 **locals() 传给 translate_stream
    **kwarg: Any,
):
    if not files:
        raise PDFValueError("No files to process.")

    missing_files = check_files(files)

    if missing_files:
        print("The following files do not exist:", file=sys.stderr)
        for file in missing_files:
            print(f"  {file}", file=sys.stderr)
        raise PDFValueError("Some files do not exist.")

    result_files = []

    for file in files:
        if type(file) is str and (
            file.startswith("http://") or file.startswith("https://")
        ):
            print("Online files detected, downloading...")
            try:
                r = requests.get(file, allow_redirects=True)
                if r.status_code == 200:
                    with tempfile.NamedTemporaryFile(
                        suffix=".pdf", delete=False
                    ) as tmp_file:
                        print(f"Writing the file: {file}...")
                        tmp_file.write(r.content)
                        file = tmp_file.name
                else:
                    r.raise_for_status()
            except Exception as e:
                raise PDFValueError(
                    f"Errors occur in downloading the PDF file. Please check the link(s).\nError:\n{e}"
                )
        filename = os.path.splitext(os.path.basename(file))[0]

        # If the commandline has specified converting to PDF/A format
        # --compatible / -cp
        if compatible:
            with tempfile.NamedTemporaryFile(
                suffix="-pdfa.pdf", delete=False
            ) as tmp_pdfa:
                print(f"Converting {file} to PDF/A format...")
                convert_to_pdfa(file, tmp_pdfa.name)
                doc_raw = open(tmp_pdfa.name, "rb")
                os.unlink(tmp_pdfa.name)
        else:
            doc_raw = open(file, "rb")
        s_raw = doc_raw.read()
        doc_raw.close()

        if file.startswith(tempfile.gettempdir()):
            os.unlink(file)
        s_mono, s_dual = translate_stream(
            s_raw,
            **locals(),
        )
        file_mono = Path(output) / f"{filename}-mono.pdf"
        file_dual = Path(output) / f"{filename}-dual.pdf"
        doc_mono = open(file_mono, "wb")
        doc_dual = open(file_dual, "wb")
        doc_mono.write(s_mono)
        doc_dual.write(s_dual)
        doc_mono.close()
        doc_dual.close()
        result_files.append((str(file_mono), str(file_dual)))

    return result_files


def _font_file_ok(path) -> bool:
    """v2.3.43: 检查字体文件是否完整。下载中途断掉会留下半截文件：表目录还在，能被当成字体加载、
    能算字宽，但字形数据缺了一截 → 译文排好了版却一个汉字都画不出来（只剩数字和英文），
    换哪个翻译模型都一样，而且之后每次都直接用这个坏文件。这里按 TrueType/OpenType 表目录核对：
    每张表的 offset+length 都不能超出文件大小。"""
    try:
        size = os.path.getsize(path)
        if size < 100_000:
            return False
        with open(path, "rb") as f:
            head = f.read(12)
            if head[:4] == b"ttcf":
                return True
            num = int.from_bytes(head[4:6], "big")
            if not 0 < num < 100:
                return False
            recs = f.read(16 * num)
        for i in range(num):
            off = int.from_bytes(recs[16 * i + 8:16 * i + 12], "big")
            length = int.from_bytes(recs[16 * i + 12:16 * i + 16], "big")
            if off + length > size:
                return False
        return True
    except Exception:
        return False


def download_remote_fonts(lang: str):
    URL_PREFIX = "https://github.com/timelic/source-han-serif/releases/download/main/"
    LANG_NAME_MAP = {
        **{la: "GoNotoKurrent-Regular.ttf" for la in noto_list},
        **{
            la: f"SourceHanSerif{region}-Regular.ttf"
            for region, langs in {
                "CN": ["zh-cn", "zh-hans", "zh"],
                "TW": ["zh-tw", "zh-hant"],
                "JP": ["ja"],
                "KR": ["ko"],
            }.items()
            for la in langs
        },
    }
    font_name = LANG_NAME_MAP.get(lang, "GoNotoKurrent-Regular.ttf")

    # docker
    font_path = ConfigManager.get("NOTO_FONT_PATH", Path("/app", font_name).as_posix())
    # v2.3.43: 配置里指定的字体存在但不完整，也当作没有
    if not (Path(font_path).exists() and _font_file_ok(font_path)):
        # v2.3.39: 先用 App 自带的字体（Resources/assets/<字体名>，目前自带 SourceHanSerifCN）。
        # 之前 NOTO_FONT_PATH 默认是 docker 路径 /app/…，Mac 上不存在 → 退到系统临时目录 →
        # 没有就从 GitHub 下载；国内连不上 GitHub、或 macOS 清理了临时目录时，翻译直接失败。
        import sys as _sys
        _base = getattr(_sys, "_MEIPASS", None)
        if _base:
            _p = Path(_base, "assets", font_name)
            if _p.exists() and _font_file_ok(_p):
                return _p.as_posix()
        font_path = Path(tempfile.gettempdir(), font_name).as_posix()
        # v2.3.43: 临时目录里的是之前没下完的半截文件 → 删掉重下
        if Path(font_path).exists() and not _font_file_ok(font_path):
            try:
                os.remove(font_path)
            except OSError:
                pass
    if not Path(font_path).exists():
        print(f"Downloading {font_name}...")
        # v2.3.43: 先下到 .part，下完整、校验通过才改名，避免中断后留下半截文件被一直沿用
        part = font_path + ".part"
        urllib.request.urlretrieve(f"{URL_PREFIX}{font_name}", part)
        if not _font_file_ok(part):
            try:
                os.remove(part)
            except OSError:
                pass
            raise RuntimeError(f"中文字体 {font_name} 下载不完整，请检查网络后重试")
        os.replace(part, font_path)

    return font_path
